const sd = $getWorkflowStaticData('global');
sd.serperResults = [];
sd.acceptedCount = 0;
sd.rejected = { not_duqm: 0, no_cr: 0, parse_error: 0, excluded_entity: 0, non_oman_vendor: 0 };
return [{ json: { started_at: new Date().toISOString() } }];

const BASE = [
  '"construction company" Duqm Oman site:.om',
  '"EPC contractor" "Duqm Special Economic Zone" site:.om',
  '"heavy equipment rental" Duqm site:.om',
  '"civil engineering" "Al Duqm" site:.om',
  '"concrete batching" Duqm Oman site:.om',
  '"mining contractor" Duqm Oman site:.om',
  '"quarry" Duqm Oman site:.om',
  '"industrial contractor" SEZAD Duqm site:.om',
  '"earthmoving" contractor Duqm Oman site:.om',
  '"piling" contractor Duqm site:.om',
];

let templates = [];
let duqmKeywords = ['Duqm', 'Al Duqm', 'SEZAD', 'Duqm Port'];
for (const row of $('Load Config').all().map((i) => i.json)) {
  if (!row.icp_json || row.icp_json === 'icp_json') continue;
  try {
    const icp = JSON.parse(row.icp_json);
    if (Array.isArray(icp.search_query_templates)) templates = icp.search_query_templates;
    if (Array.isArray(icp.duqm_keywords) && icp.duqm_keywords.length) duqmKeywords = icp.duqm_keywords;
  } catch (e) {}
}

const expanded = [];
for (const tpl of templates) {
  const t = String(tpl);
  if (t.includes('{keyword}')) {
    for (const kw of duqmKeywords.slice(0, 4)) expanded.push(t.replace(/\{keyword\}/g, kw));
  } else {
    expanded.push(t);
  }
}

const all = [...new Set([...BASE, ...expanded])].filter(Boolean);
return all.map((query) => ({ json: { query } }));

const sd = $getWorkflowStaticData('global');
const results = sd.serperResults || [];

let existing = [];
try {
  existing = $('Load Companies').all().map((i) => i.json).filter((r) => r.company_name && r.company_name !== 'company_name');
} catch (e) { existing = []; }

const existingDomains = new Set();
const existingUrls = new Set();
for (const row of existing) {
  if (row.website) {
    const d = extractDomain(row.website);
    if (d) existingDomains.add(d);
  }
  if (row.duqm_evidence_url) existingUrls.add(String(row.duqm_evidence_url).toLowerCase());
}

const skipDomainsSerper = [
  'facebook.com', 'linkedin.com', 'youtube.com', 'instagram.com', 'twitter.com', 'x.com', 'wikipedia.org',
  'google.com', 'greenhouse.io', 'yahoo.com', 'ndtvprofit.com', 'volza.com', 'thisdaylive.com', 'omanobserver.om',
  'omanobserver.com', 'timesofoman.com', 'muscatdaily.com', 'scribd.com', 'miga.org', 'aiib.org', 'magazine.', 'news.',
  'omantenders', 'infinitetalent', 'allplan.com', 'devex.com', 'yellowpages', 'portofduqm', 'tpo.om', 'gov.om',
  'saipem.com', 'hellenicshippingnews', 'deltongroup.com',
];

const seen = new Set();
const out = [];
const stats = { no_link: 0, bad_url: 0, skip_domain: 0, skip_non_om: 0, existing: 0, added: 0 };

function normalizeLink(raw) {
  const link = String(raw || '').trim();
  if (!link) return '';
  return /^https?:\/\//i.test(link) ? link : `https://${link}`;
}

function extractDomain(raw) {
  const link = normalizeLink(raw);
  if (!link) return '';
  const m = link.match(/^https?:\/\/([^/?#]+)/i);
  if (!m) return '';
  return m[1].replace(/^www\./i, '').toLowerCase();
}

function scoreCandidate(c, domain) {
  let score = 0;
  const blob = `${c.title || ''} ${c.snippet || ''}`.toLowerCase();
  if (domain.endsWith('.om')) score += 35;
  if (/contracting|engineering|construction|cement|quarries|equipment|infrastructure/i.test(blob)) score += 20;
  if (/duqm|sezad/i.test(blob)) score += 15;
  if (/\.om$/i.test(domain) && /contract|engineer|quarr|cement|equip|infra|logistic|industrial|port|mining|build/i.test(domain)) score += 25;
  if (/\.(pdf|gov\.om|sam\.gov|miga\.org|aiib\.org)/i.test(domain)) score -= 40;
  if (/linkedin|facebook|instagram|news|magazine|finance\.|observer|ndtv|scribd|yahoo|volza|tender|recruit|manpower|talent/i.test(domain)) score -= 50;
  return score;
}

function add(c) {
  const link = normalizeLink(c.link || c.Link);
  if (!link) { stats.no_link++; return; }
  const key = link.toLowerCase();
  if (seen.has(key)) return;
  const domain = extractDomain(link);
  if (!domain) { stats.bad_url++; return; }
  if (!domain.endsWith('.om')) { stats.skip_non_om++; return; }
  if (skipDomainsSerper.some((d) => domain.includes(d))) { stats.skip_domain++; return; }
  if (existingUrls.has(key)) { stats.existing++; return; }
  if (existingDomains.has(domain)) { stats.existing++; return; }
  seen.add(key);
  stats.added++;
  out.push({
    json: {
      title: c.title || c.Title || '', snippet: c.snippet || c.Snippet || '', link,
      position: c.position || 0, source: c.source || 'serper',
      domain, result_url: link, priority_score: scoreCandidate(c, domain),
    },
  });
}

for (const r of results) add(r);

out.sort((a, b) => (b.json.priority_score || 0) - (a.json.priority_score || 0));
sd.candidateStats = stats;
sd.candidateCount = out.length;
return out.length ? out : [{ json: { empty: true, stats } }];

const cand = $('Loop Candidates').item.json;
const raw = $input.item.json;
const html = typeof raw === 'string' ? raw : (raw.data ?? raw.body ?? JSON.stringify(raw));
const text = String(html)
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 40000);
return {
  json: {
    ...cand,
    page_text: text,
    combined_text: [`${cand.title || ''} ${cand.snippet || ''}`, text].join(' ').slice(0, 45000),
  },
};

values.content:
=Extract company information from this search result for B2B lead generation in Duqm, Oman.

Return JSON with exactly these keys:
- company_name: string (official company name, not page title)
- website: string (company homepage URL if identifiable, else empty)
- industry_guess: string (e.g. EPC, civil construction, port logistics, equipment rental)
- duqm_evidence: string (quote or phrase proving Duqm/Al Duqm/SEZAD/Duqm Port relevance)
- relevance_score: number 0-100 (Zoomlion heavy-equipment buyer fit)
- duqm_verified: boolean (true ONLY if text mentions Duqm, Al Duqm, SEZAD, Duqm Port, or Duqm SEZ)

Search result URL: {{ $json.result_url || $json.link }}
Title: {{ $json.title }}
Snippet: {{ $json.snippet }}

Page text:
{{ $json.combined_text }}

parameters.jsCode:
const base = $('Strip Page HTML').item.json;
const gemini = $input.item.json;
let data = gemini;

const extractText = (v) => {
  if (typeof v === 'string') return v;
  if (v?.content?.parts?.[0]?.text) return v.content.parts[0].text;
  if (v?.parts?.[0]?.text) return v.parts[0].text;
  return null;
};

const textPayload = extractText(gemini);
if (textPayload) {
  try { data = JSON.parse(textPayload); } catch (e) {
    const m = textPayload.match(/\{[\s\S]*\}/);
    if (m) data = JSON.parse(m[0]);
  }
} else if (typeof gemini.text === 'string') {
  try { data = JSON.parse(gemini.text); } catch (e) {
    const m = gemini.text.match(/\{[\s\S]*\}/);
    if (m) data = JSON.parse(m[0]);
  }
} else if (gemini.output) {
  data = typeof gemini.output === 'string' ? JSON.parse(gemini.output) : gemini.output;
}

const DUQM_RE = /\b(duqm|al\s*duqm|sezad|duqm\s*port|duqm\s*sez|special\s*economic\s*zone)\b/i;
const combined = `${base.combined_text || ''} ${base.snippet || ''} ${base.title || ''} ${data.duqm_evidence || ''}`;

const EXCLUDED_NAME = [
  /public authority/i, /special economic zone/i, /economic zone authority/i,
  /free zones?/i, /\bsezad\b/i, /zone authority/i, /mem\b/i,
  /recruitment/i, /manpower/i, /staffing/i, /\btalent\b/i, /headhunt/i,
  /job portal/i, /employment agency/i,
];
const EXCLUDED_INDUSTRY = [
  /recruitment/i, /manpower/i, /staffing/i, /software/i, /saas/i,
  /authority/i, /economic zone/i,
];

const badHosts = [
  'scribd.com', 'facebook.com', 'linkedin.com', 'instagram.com', 'twitter.com', 'x.com', 'youtube.com',
  'wikipedia.org', 'google.com', 'sam.gov', 'omanobserver.om', 'omanobserver.com', 'ndtvprofit.com',
  'thisdaylive.com', 'yahoo.com', 'volza.com', 'miga.org', 'aiib.org', 'greenhouse.io', 'magazine.', 'news.',
  'omantenders', 'infinitetalent', 'allplan.com', 'devex.com', 'yellowpages', 'portofduqm', 'tpo.om',
];

const hostFromUrl = (url) => {
  try {
    const u = new URL(url.startsWith('http') ? url : `https://${url}`);
    return u.hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) { return ''; }
};

const hostBad = (url) => {
  const h = hostFromUrl(url);
  return !h || badHosts.some((b) => h.includes(b));
};

const companyTokens = (name) => String(name || '')
  .toLowerCase()
  .replace(/\b(llc|l\.l\.c|spc|s\.p\.c|company|contracting|co|oman|duqm|al|the|saoc|group|trading|services|engineering)\b/g, ' ')
  .split(/\s+/)
  .map((t) => t.replace(/[^a-z0-9]/g, ''))
  .filter((t) => t.length >= 4);

const domainMatchesCompany = (domain, name) => {
  const tokens = companyTokens(name);
  return tokens.some((t) => domain.includes(t));
};

const companyName = String(data.company_name || base.title || '').trim();
const industry = String(data.industry_guess || '').trim();

const isExcludedEntity = EXCLUDED_NAME.some((r) => r.test(companyName))
  || EXCLUDED_INDUSTRY.some((r) => r.test(industry));

let website = String(data.website || '').trim();

if (!website || hostBad(website)) {
  if (base.domain && !badHosts.some((h) => base.domain.includes(h))) {
    website = `https://${base.domain}`;
  } else {
    website = '';
  }
}

const websiteHost = hostFromUrl(website);
if (website && (hostBad(website) || !domainMatchesCompany(websiteHost, companyName))) {
  if (base.domain && domainMatchesCompany(base.domain, companyName)) {
    website = `https://${base.domain}`;
  } else if (base.result_url && !hostBad(base.result_url)) {
    const rh = hostFromUrl(base.result_url);
    website = domainMatchesCompany(rh, companyName) ? `https://${rh}` : '';
  } else {
    website = '';
  }
}

const finalHost = hostFromUrl(website);
const hasOmanPresence = finalHost.endsWith('.om')
  || /\b(oman|duqm|muscat|sultanate of oman)\b/i.test(combined);
const isNonOmanVendor = Boolean(finalHost) && !finalHost.endsWith('.om') && !hasOmanPresence;

let rejection_reason = '';
if (isExcludedEntity) rejection_reason = 'excluded_entity';
else if (isNonOmanVendor) rejection_reason = 'non_oman_vendor';

const duqmVerified = !isExcludedEntity && !isNonOmanVendor && (
  Boolean(data.duqm_verified)
  || DUQM_RE.test(combined)
  || DUQM_RE.test(String(data.duqm_evidence || ''))
  || DUQM_RE.test(`${base.snippet || ''} ${base.title || ''}`)
);

if (!duqmVerified && !rejection_reason) rejection_reason = 'not_in_duqm';

return {
  json: {
    ...base,
    company_name: companyName,
    website,
    industry,
    duqm_evidence: String(data.duqm_evidence || base.snippet || '').trim(),
    relevance_score: Number(data.relevance_score) || 0,
    duqm_verified: duqmVerified,
    rejection_reason,
  },
};

const item = $input.item.json;
const badHosts = ['omanobserver', 'scribd', 'ndtv', 'thisdaylive', 'yahoo', 'volza', 'miga', 'aiib', 'linkedin', 'facebook', 'news', 'magazine'];

let origin = '';
if (item.domain && !badHosts.some((b) => String(item.domain).includes(b))) {
  origin = `https://${item.domain}`;
} else if (item.website) {
  try { origin = new URL(item.website.startsWith('http') ? item.website : `https://${item.website}`).origin; } catch (e) { origin = ''; }
}
if (!origin && item.result_url) {
  try {
    const d = new URL(item.result_url).hostname;
    if (!badHosts.some((b) => d.includes(b)) && d.endsWith('.om')) origin = `https://${d}`;
  } catch (e) {}
}

return {
  json: {
    ...item,
    website: origin || item.website || '',
    about_url: origin ? `${origin}/about` : '',
    contact_url: origin ? `${origin}/contact-us` : '',
    page_text: item.page_text || '',
  },
};

const strip = (raw) => {
  const html = typeof raw === 'string' ? raw : (raw?.data ?? raw?.body ?? '');
  return String(html)
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 20000);
};
const base = $('Prepare Extra Pages').item.json;
const aboutRaw = $('Fetch About Page').item.json;
const contactRaw = $input.item.json;
return {
  json: {
    ...base,
    about_text: strip(aboutRaw),
    contact_text: strip(contactRaw),
    all_text: [base.page_text, strip(aboutRaw), strip(contactRaw), base.combined_text].join(' ').slice(0, 60000),
  },
};

const item = $input.item.json;
const text = item.all_text || '';
const patterns = [
  /(?:CR|C\.R\.|Commercial\s*Registration|Trade\s*License|Reg\.?\s*No\.?|رقم\s*السجل\s*التجاري)[^0-9]{0,30}([0-9]{5,12})/gi,
  /(?:License|Licence)\s*(?:No\.?|Number|#)[^0-9]{0,15}([0-9]{5,12})/gi,
  /\bCR\s*[#:]?\s*([12]\d{6})\b/gi,
  /\b([12]\d{6})\b/g,
];
const found = [];
for (const re of patterns) {
  let m;
  while ((m = re.exec(text)) !== null) {
    const num = m[1];
    if (num && num.length >= 5 && num.length <= 10 && !found.includes(num)) found.push(num);
  }
}
const nearCr = text.match(/(?:CR|registration|license|commercial)[^0-9]{0,40}([12]\d{6})/i);
if (nearCr && !found.includes(nearCr[1])) found.push(nearCr[1]);

// Prefer 7-digit Oman CR numbers
const preferred = found.find((n) => /^[12]\d{6}$/.test(n)) || found[0] || '';

return {
  json: {
    ...item,
    website_cr_candidates: found,
    cr_number: preferred,
    cr_source_url: preferred ? (item.website || item.result_url) : '',
    cr_source: preferred ? 'website' : '',
  },
};

const base = $('Website CR Extract').item.json;
if (base.cr_number) return { json: base };
const organic = $input.item.json.organic || [];
const re = /(?:CR|Commercial\s*Registration|Trade\s*License|Reg\.?\s*No\.?)[^0-9]{0,25}([0-9]{4,12})/gi;
let cr = '';
let source = '';
for (const r of organic) {
  const blob = `${r.title || ''} ${r.snippet || ''}`;
  let m;
  while ((m = re.exec(blob)) !== null) {
    if (m[1] && m[1].length >= 5) { cr = m[1]; source = r.link; break; }
  }
  if (cr) break;
}
return { json: { ...base, cr_number: cr, cr_source_url: source || base.cr_source_url, cr_source: cr ? 'serper_cr' : base.cr_source } };

const base = $('Parse Serper CR').item.json;
if (base.cr_number) return { json: base };
const organic = $input.item.json.organic || [];
const re = /(?:CR|Commercial\s*Registration)[^0-9]{0,20}([0-9]{5,12})/gi;
let cr = '';
let source = '';
for (const r of organic) {
  const blob = `${r.title || ''} ${r.snippet || ''}`;
  const m = re.exec(blob);
  re.lastIndex = 0;
  if (m) { cr = m[1]; source = r.link; break; }
}
return { json: { ...base, cr_number: cr || base.cr_number, cr_source_url: source || base.cr_source_url, cr_source: cr ? 'serper_pdf' : base.cr_source } };

const base = $('Parse PDF CR').item.json;
if (base.cr_number) return { json: base };
const organic = $input.item.json.organic || [];
const re = /(?:CR|Commercial\s*Registration|Trade\s*License|Reg\.?\s*No\.?)[^0-9]{0,25}([0-9]{5,12})/gi;
let cr = '';
let source = '';
for (const r of organic) {
  const blob = `${r.title || ''} ${r.snippet || ''}`;
  const m = re.exec(blob);
  re.lastIndex = 0;
  if (m) { cr = m[1]; source = r.link; break; }
}
if (!cr && base.company_name && base.all_text) {
  const name = String(base.company_name).split(/\s+/).slice(0, 2).join(' ');
  const idx = base.all_text.toLowerCase().indexOf(name.toLowerCase());
  if (idx >= 0) {
    const window = base.all_text.slice(Math.max(0, idx - 80), idx + 300);
    const wm = window.match(/(?:CR|registration|license|commercial)[^0-9]{0,30}([12]\d{6})/i) || window.match(/\b([12]\d{6})\b/);
    if (wm) { cr = wm[1]; source = base.website || base.result_url || source; }
  }
}
// Last resort: any standalone 7-digit CR in combined text near Duqm context
if (!cr && base.all_text) {
  const all = [...base.all_text.matchAll(/\b([12]\d{6})\b/g)].map((m) => m[1]);
  const uniq = [...new Set(all)];
  if (uniq.length === 1) { cr = uniq[0]; source = base.website || base.result_url || source; }
}
return { json: { ...base, cr_number: cr || base.cr_number, cr_source_url: source || base.cr_source_url, cr_source: cr ? 'serper_variant' : base.cr_source } };

values.content:
=Pick the best matching Oman commercial registration (CR) number for this company.

Company: {{ $json.company_name }}
Website: {{ $json.website }}
Candidates from website: {{ $json.website_cr_candidates }}
Current best CR: {{ $json.cr_number }}
Source: {{ $json.cr_source }}

Return JSON: { "cr_number": "...", "cr_source_url": "...", "confidence": "high|medium|low", "notes": "..." }
If none are valid, return empty cr_number.

parameters.jsCode:
const base = $('Parse Variant CR').item.json;
const gemini = $input.item.json;
let picked = base;

const extractText = (v) => {
  if (typeof v === 'string') return v;
  if (v?.content?.parts?.[0]?.text) return v.content.parts[0].text;
  if (v?.parts?.[0]?.text) return v.parts[0].text;
  return null;
};

const needsDisambig = (base.website_cr_candidates || []).length > 1 && base.cr_number;
if (needsDisambig) {
  const textPayload = extractText(gemini);
  if (textPayload) {
    try {
      const parsed = JSON.parse(textPayload.match(/\{[\s\S]*\}/)?.[0] || textPayload);
      if (parsed.cr_number) {
        picked = { ...base, cr_number: String(parsed.cr_number), cr_source_url: parsed.cr_source_url || base.cr_source_url, cr_notes: parsed.notes || '' };
      }
    } catch (e) {}
  }
}

const cr = String(picked.cr_number || '').trim();
return { json: { ...picked, cr_number: cr, has_cr: Boolean(cr) } };

const item = $input.item.json;
const sd = $getWorkflowStaticData('global');
sd.acceptedCount = (sd.acceptedCount || 0) + 1;
return {
  json: {
    company_name: item.company_name,
    cr_number: item.cr_number,
    website: item.website || '',
    industry: item.industry || '',
    duqm_evidence_url: item.result_url || item.duqm_evidence_url || '',
    cr_source_url: item.cr_source_url || '',
    relevance_score: item.relevance_score || 0,
    status: 'cr_verified',
  },
};

const sd = $getWorkflowStaticData('global');
sd.rejected.no_cr = (sd.rejected.no_cr || 0) + 1;
return { json: { rejected: 'no_cr', company: $json.company_name, url: $json.result_url } };

const base = $('Parse Variant CR').item.json;
const cr = String(base.cr_number || '').trim();
return { json: { ...base, cr_number: cr, has_cr: Boolean(cr) } };

const sd = $getWorkflowStaticData('global');
const reason = String($json.rejection_reason || 'not_duqm');
if (reason === 'excluded_entity') sd.rejected.excluded_entity = (sd.rejected.excluded_entity || 0) + 1;
else if (reason === 'non_oman_vendor') sd.rejected.non_oman_vendor = (sd.rejected.non_oman_vendor || 0) + 1;
else sd.rejected.not_duqm = (sd.rejected.not_duqm || 0) + 1;
return { json: { rejected: reason, company: $json.company_name, url: $json.result_url } };

const sd = $getWorkflowStaticData('global');
if (!sd.serperResults) sd.serperResults = [];
const organic = $input.item.json.organic || [];
const query = $('Loop Queries').item.json.query;
for (const r of organic) {
  sd.serperResults.push({
    title: r.title || '',
    link: r.link || '',
    snippet: r.snippet || '',
    position: r.position || 0,
    query,
  });
}
return { json: { query, result_count: organic.length } };

const BAD_WEBSITE = ['scribd.com', 'omanobserver', 'linkedin.com', 'ndtv', 'thisdaylive', 'yahoo', 'volza', 'miga.org', 'aiib.org', 'omantenders', 'infinitetalent', 'allplan', 'portofduqm', 'tpo.om', 'yellowpages', 'gov.om', 'cgc-kw.com', 'alkhaleejmining.com'];
const EXCLUDED_COMPANY = /public authority|special economic zone|sezad|recruitment|manpower|staffing|\btalent\b|allplan|infinitetalent|infrastructure investment bank|\baiib\b/i;
const PENDING_STATUS = new Set(['cr_verified', 'needs_domain', 'needs_contact', 'needs_review']);

const isBadWebsite = (url) => {
  const s = String(url || '').toLowerCase();
  return BAD_WEBSITE.some((b) => s.includes(b));
};

const hostFromUrl = (url) => {
  const s = String(url || '').trim();
  if (!s) return '';
  const cleaned = s.replace(/^https?:\/\//i, '').replace(/^www\./i, '');
  return cleaned.split('/')[0].toLowerCase();
};

const rows = $('Load Companies1').all().map((i) => i.json)
  .filter((r) => r.company_name && r.company_name !== 'company_name')
  .filter((r) => !EXCLUDED_COMPANY.test(String(r.company_name)) && !EXCLUDED_COMPANY.test(String(r.industry || '')))
  .filter((r) => {
    const host = hostFromUrl(r.website);
    if (host && !host.endsWith('.om')) return false;
    return true;
  })
  .filter((r) => {
    const status = String(r.status || '').toLowerCase();
    if (PENDING_STATUS.has(status)) return true;
    if (status === 'enriched' && isBadWebsite(r.website)) return true;
    return false;
  })
