};

const safeParse = (text) => {
  if (!text) return {};
  try { return JSON.parse(text); } catch (e) {
    const m = String(text).match(/\{[\s\S]*\}/);
    if (!m) return {};
    try { return JSON.parse(m[0]); } catch (e2) { return {}; }
  }
};

const textPayload = extractText(gemini);
if (textPayload) data = safeParse(textPayload);
else if (typeof gemini.text === 'string') data = safeParse(gemini.text);
else if (gemini.output) data = typeof gemini.output === 'string' ? safeParse(gemini.output) : (gemini.output || {});
else if (gemini && typeof gemini === 'object') data = gemini;

const notes = String(data.notes || '').trim();
const notesLower = notes.toLowerCase();
const mismatchPhrases = [
  'wrong company', 'newspaper', 'media outlet', 'rather than', 'does not belong',
  'do not belong', 'not duqm', 'mismatch', 'unrelated', 'does not match', 'belong to the',
  'oman daily observer', 'oman observer', 'not the company', 'incorrect domain',
];
const notesMismatch = mismatchPhrases.some((p) => notesLower.includes(p));

let jobTitle = String(data.job_title || '').trim();
const contactName = String(data.contact_name || '').trim() || 'Not Available';
let sourceUrls = data.source_urls || [];
if (!Array.isArray(sourceUrls)) sourceUrls = String(sourceUrls || '').split(',').map((s) => s.trim()).filter(Boolean);
if (!sourceUrls.length && base.contact_url_used) sourceUrls.push(base.contact_url_used);
if (!sourceUrls.length && base.domain) sourceUrls.push('https://' + base.domain);

const hunter = (base.hunter_emails || [])[0];
const finalEmail = String(data.email || (hunter && hunter.email) || '').trim();
let finalTitle = jobTitle || (hunter && hunter.position) || '';
if (finalTitle.toLowerCase() === 'not available') finalTitle = (hunter && hunter.position) || '';

if (!finalTitle && finalEmail.includes('@')) {
  const local = finalEmail.split('@')[0].toLowerCase();
  const roleMap = {
    procurement: 'Procurement Manager',
    operations: 'Operations Manager',
    projects: 'Project Manager',
    project: 'Project Manager',
    info: 'General Contact',
    sales: 'Sales Manager',
    admin: 'Office Manager',
    support: 'General Contact',
  };
  for (const [key, title] of Object.entries(roleMap)) {
    if (local.includes(key)) { finalTitle = title; break; }
  }
}
if (!finalTitle && finalEmail) finalTitle = 'General Contact';

const pagePhone = (base.page_phones || [])[0] || '';
const finalPhone = String(data.phone || pagePhone || '').trim();

const companyDomain = String(base.domain || '').toLowerCase();
const emailDomain = finalEmail.includes('@') ? finalEmail.split('@')[1].toLowerCase() : '';

const emailDomainOk = (() => {
  if (!finalEmail.includes('@')) return false;
  if (!emailDomain.endsWith('.om')) return false;
  if (emailDomain.includes('gov.om')) return false;
  if (!companyDomain) return true;
  if (emailDomain === companyDomain || emailDomain.endsWith('.' + companyDomain) || companyDomain.endsWith(emailDomain)) return true;
  const tokens = String(base.company_name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').split(/\s+/).filter((t) => t.length >= 4);
  return tokens.some((t) => emailDomain.includes(t));
})();

